probe.scriptUtf8:
import assert from 'node:assert/strict';
import {execFileSync} from 'node:child_process';
import {mkdtemp,rm} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import {join,resolve} from 'node:path';
import {createRequire} from 'node:module';
import {_electron as electron,expect} from '@playwright/test';
const require=createRequire(resolve('apps/desktop/package.json'));
const csv=execFileSync('git',['show','11826e4dedb6df1c2593fe061f8b7517527a3c73:wiki-project/demo_data/catalog_demo.csv'],{encoding:'utf8'});
const directory=await mkdtemp(join(tmpdir(),'c-demo-quotes-'));
const launch=()=>electron.launch({executablePath:require('electron'),args:[resolve('apps/desktop/out/main/index.js')],env:{...process.env,ELECTRON_RUN_AS_NODE:'',TRADEQUOTE_TEST_DATA:directory}});
const cases=[['1601053415993','3','129.57'],['1601053415993','50','2060.00'],['1601053415993','100','3921.00'],['1601053415993','500','18605.00'],['1601926123092','5','124.60'],['1601926123092','500','11730.00'],['1601926123092','1000','22200.00'],['1601926123092','10000','210000.00'],['MDF-001','100','350.00'],['MDF-001','500','1600.00'],['MDF-001','1000','2950.00'],['BOLT-001','1','1.30'],['BOLT-001','5','5.50'],['BOLT-001','10','9.50']];
let app;
try{
 app=await launch();let page=await app.firstWindow();
 await page.getByRole('link',{name:'创建工作区',exact:true}).click();await page.getByLabel('工作区名称').fill('C独立报价路径');await page.getByRole('button',{name:'创建工作区',exact:true}).click();await expect(page.getByText('已保存至本机 · 版本 1')).toBeVisible();
 await page.getByRole('link',{name:'资料与报价'}).click();await page.getByRole('button',{name:'保存演示场景'}).click();await expect(page.getByText('场景版本 1',{exact:true})).toBeVisible();
 await page.getByLabel('CSV 原文').fill(csv);await page.getByLabel('资料名称').fill('catalog_demo.csv');await page.getByLabel('资料性质').selectOption('synthetic');await page.getByRole('button',{name:'解析并预览'}).click();await expect(page.getByRole('button',{name:'确认发布此批次'})).toBeEnabled();await page.getByRole('button',{name:'确认发布此批次'}).click();await expect(page.getByRole('checkbox',{name:'选择 MDF-001',exact:true})).toBeVisible();
 const saved=[];
 for(const [sku,quantity,total] of cases){
 const result=await page.evaluate(async ({sku,quantity})=>{const b=await window.tradequote.getTrade();if(!b.ok)throw Error('board');const p=b.data.products.find(p=>p.sku===sku);if(!p||!b.data.scenario)throw Error('fixture');return window.tradequote.createQuoteV1({schemaVersion:1,requestId:crypto.randomUUID(),idempotencyKey:crypto.randomUUID(),method:'quote.createV1',payload:{scenarioId:b.data.scenario.id,buyer:'C测试买方',inquiry:'仅技术验证',payment:'',delivery:'',lines:[{productId:p.id,quantity,unit:p.unit}]}});},{sku,quantity});
 assert.equal(result.ok,true,JSON.stringify(result));const q=result.data.quotes.find(q=>!saved.some(old=>old.id===q.id));assert.equal(q.goodsTotal,total);assert.equal(q.lines[0].tierMin,quantity);saved.push(q);
 }
 const mixed=await page.evaluate(async()=>{const b=await window.tradequote.getTrade();const picks=['1601053415993','MDF-001'].map(sku=>b.data.products.find(p=>p.sku===sku));return window.tradequote.createQuoteV1({schemaVersion:1,requestId:crypto.randomUUID(),idempotencyKey:crypto.randomUUID(),method:'quote.createV1',payload:{scenarioId:b.data.scenario.id,buyer:'C测试',inquiry:'混币拒绝',payment:'',delivery:'',lines:picks.map(p=>({productId:p.id,quantity:'100',unit:p.unit}))}});});
 assert.equal(mixed.ok,false);assert.equal(mixed.error.code,'VALIDATION_ERROR');
 const before=await page.evaluate(()=>window.tradequote.getTrade());assert.equal(before.data.quotes.length,14);
 await app.close();app=await launch();page=await app.firstWindow();await page.getByRole('link',{name:'资料与报价'}).click();await expect(page.getByRole('checkbox',{name:'选择 MDF-001',exact:true})).toBeVisible();
 const after=await page.evaluate(()=>window.tradequote.getTrade());assert.deepEqual(after.data.quotes,before.data.quotes);
 console.log(JSON.stringify({status:'passed',tierCases:cases,savedQuotes:14,mixedCurrency:'VALIDATION_ERROR; no new quote',restart:'all 14 quote snapshots byte-equivalent as JSON',scope:'UI import/publish; public preload/main/worker quote commands; real Electron restart; no FX/model call'}));
}finally{if(app)await app.close();await rm(directory,{recursive:true,force:true});}
